bool isPalindrome(char *s, int len) {
	Init(&X);
	for (int i = 0; i < len; i = i + 1)
		Add(X, s[i]);

	int n = len;
	while (n > 1) {
		if (getFirst(X) != getLast(X)))
			return 0;
		n = n - 2;
	}
	Clear(&X);
	return 1;
}

